def is_tree(n, edges):
    if len(edges) != n - 1:
        return False

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    parent = [-1] * (n + 1)

    def bfs(start):
        queue = deque([start])
        visited[start] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    return False
        return True

    if not bfs(1):
        return False

    return all(visited[1:])

